const e=JSON.parse('{"chat":{"model_search":"Modelle suchen","model_show_more":"Weitere Modelle anzeigen","model_show_fewer":"Weniger Modelle anzeigen","model_refresh":"Modelle aktualisieren","model_no_matches":"Keine passenden Modelle. Verbinde einen Provider oder aktualisiere die Liste.","model_group_anthropic":"Anthropic-Subscription","model_group_chatgpt":"ChatGPT- / Codex-Subscription","model_group_grok":"Grok-Subscription","model_group_google":"Google- / Gemini-Subscription","model_scope":"Gilt für die nächsten Nachrichten und Routinen dieses Agenten. Der Chatverlauf bleibt erhalten.","model_busy":"Warte auf die laufende Antwort, bevor du das Modell wechselst.","model_save_failed":"Das Modell konnte nicht gespeichert werden","model_load_failed":"Verbundene Provider konnten nicht geladen werden. Schließe die Auswahl und versuche es erneut.","model_provider":"Provider","model_choose_provider":"Verbundenen Provider wählen","model_account":"Konto","model_active_account":"Aktives Konto","model_connections":"Nur verbundene Provider werden angezeigt. Weitere Zugänge findest du in den Einstellungen.","model_saving":"Wird gespeichert…","model_apply":"Modell übernehmen"},"world":{"talk_kind_query":"fragt","talk_kind_answer":"antwortet","talk_kind_propose":"schlägt vor","talk_digest":"+{0} weitere","talk_listening":"hört zu","talk_calling":"ruft {0} an","talk_more":"…","hud_talking":"{0} im Gespräch","room_round":"Runde {0}/{1}","room_settled":"Runde beendet","room_reason_message_cap":"alles gesagt","room_reason_round_cap":"die Runden sind aufgebraucht","room_reason_silence":"niemand hat gesprochen","room_reason_user":"von dir beendet","room_reason_kill_switch":"die Society wurde gestoppt","mode_label":"Agenten-Ansicht","mode_world":"Welt","mode_ledger":"Ledger","hud_agents":"{count} Agenten","hud_active":"{count} aktiv","sample_badge":"Beispiel-Roster","reduced_motion_note":"Reduzierte Bewegung: die Insel steht still","controls_hint":"Ziehen zum Schwenken · Rechte Maustaste zum Drehen · Scrollen zum Zoomen · Pfeiltasten zum Bewegen · Gebäude anklicken zum Drehen","rotate_hint":"Den Knopf um das Gebäude ziehen, um es zu drehen. Mit Shift rastet es in 15°-Schritten ein.","rotate_reset":"Zurück zur Standard-Ausrichtung","rotate_reset_short":"Zurücksetzen","rotate_reset_all":"Alle Gebäude auf ihre Standard-Ausrichtung zurücksetzen","rotate_reset_all_count":"{count} gedrehte zurücksetzen","zoom_label":"Zoom","zoom_in":"Hineinzoomen","zoom_out":"Herauszoomen","compass_label":"Blickrichtung","turn_left":"Ansicht nach links drehen (Q)","turn_right":"Ansicht nach rechts drehen (E)","view_reset":"Zurück zur Standardansicht (R)","minimap_label":"Inselkarte – klicken, um dorthin zu springen","webgl_missing_title":"Die Insel braucht WebGL","webgl_missing_body":"Dieses Fenster kann gerade kein 3D zeichnen. Das Ledger zeigt dieselben Agenten.","open_ledger":"Ledger öffnen","loading":"Die Insel wird gebaut…","place_plugins":"Plugin-Docks","place_foundry":"Agent-Foundry","drawer_foundry_title":"Agent-Foundry","drawer_foundry_hint":"Hier entstehen neue Agenten. Wer gebaut wird, tritt aus dem Portal und fährt über das Förderband hinunter auf den Platz.","foundry_create":"Neuen Agenten bauen","foundry_population":"{count} Agenten leben auf der Insel","foundry_recent":"Zuletzt gebaut","foundry_none":"Noch kein Agent gebaut.","foundry_walkout":"Ein frisch gebauter Agent kommt aus dem Portal und sucht sich seinen Platz im Dorf.","drawer_plugins_title":"Plugin-Docks","drawer_plugins_hint":"Alle in dieser App installierten Plugins, nach Familie. Ein Agent geht hierher, wenn sein Lauf auf ein Plugin setzt.","drawer_open_section":"Bereich Plugins öffnen","card_kind_building":"Gebäude","cli_group_seats":"Coding-Sitze","plugin_group_connected":"Verbunden","plugin_group_available":"Verfügbar","status_connected":"Verbunden","status_available":"Nicht verbunden","status_attention":"Braucht Aufmerksamkeit","status_installed":"Installiert","status_missing":"Nicht installiert","status_checking":"Wird geprüft","status_running":"Läuft","status_stopped":"Gestoppt","status_draft":"Entwurf","status_ready":"Bereit","card_does_title":"Was es macht","card_how_title":"So nutzt du es","card_inside_title":"Gerade drin","card_open_section":"Bereich öffnen","card_create_agent":"Agent erstellen","card_drag_hint":"Ziehen zum Drehen · Rad zum Zoomen · Doppelklick setzt zurück","card_reduced_motion":"Reduzierte Bewegung: Ziehen dreht","card_unavailable":"Das Gebäude kann in diesem Fenster nicht gezeichnet werden.","card_plugins_does":"Die Plugin Docks beherbergen jedes Plugin, das in dieser App installiert ist — Gehirne, Werkzeuge, Sprache, Kanäle, Realtime, Weckwörter und Harnesses — nach Familie sortiert. Ein Agent geht hierher, sobald ein Lauf auf eines davon setzt.","card_plugins_how":"Plugins installierst oder entfernst du im Bereich Plugins; jeder Agent darf standardmäßig alle nutzen. Sag einem Agenten in seinem Chat, zu welchem Plugin er zuerst greifen soll.","card_foundry_does":"In der Agent Foundry entstehen neue Agenten. Ein frisch gebauter Agent tritt aus dem Portal und läuft hinunter zum Platz, um sich dem Team anzuschließen.","card_foundry_how":"Erstelle einen Agenten hier oder über „Neu“ in der Agentenleiste: Name, Bezeichnung, Beschreibung und der Sitz, auf dem er läuft. Alles Weitere sagst du ihm in seinem eigenen Chat.","card_skills_does":"Die Skill Forge bewahrt jeden Skill, den diese App kennt — eingebaute, deine eigenen und Entwürfe, die noch Form annehmen. Ein Skill ist ein wiederverwendbarer Ablauf, den ein Agent per Slash-Befehl ausführt.","card_skills_how":"Skills schreibst oder bearbeitest du im Bereich Skills; ein Agent kann auch aus einem Chat heraus einen entwerfen. Ein Entwurf bleibt Entwurf, bis du ihn freigibst.","card_mcp_does":"Der Relay Tower erreicht die MCP-Server, mit denen diese App verbunden ist — externe Werkzeuge, die ein Agent aufrufen kann. Die Schüssel dreht sich, solange ein Agent einen Aufruf macht.","card_mcp_how":"Server fügst du im Bereich MCPs hinzu oder entfernst sie dort. Jeder Agent erreicht jeden verbundenen Server.","card_cli_does":"In der Terminal Cantina sitzen die Coding-CLIs — Claude Code, Codex, Grok Build und die anderen — mit ihren Subscription-Logins. Ein Agent sitzt hier an einem Terminal, solange eine Coding-Sitzung läuft.","card_cli_how":"Verbinde ein CLI oder melde dich im Bereich CLIs bei einer Subscription an. Ein Agent kann dann auf diesem Sitz laufen statt über einen API-Key.","card_archive_does":"Das Memory House ist das gemeinsame Gedächtnis des Teams: geprüftes Teamwissen, das eigene Gedächtnis jedes Agenten und die Prüfliste. Ein Agent geht hierher, wenn er sich erinnert oder etwas nachschlägt.","card_archive_how":"Lies und ordne das Gedächtnis im Bereich Memory. Ein Fakt, den ein Agent vorschlägt, wartet in der Prüfliste, bis du ihn annimmst.","drawer_close":"Schließen","place_quests":"Questtafel","hud_quests":"Quests","quest_add_placeholder":"Neue Quest… z. B. die fünf wichtigsten Mails von heute","quest_wait_approval":"{agent} wartet in seinem Chat auf deine Freigabe – danach startet die Quest sofort","quest_wait_busy":"{agent} ist beschäftigt – die Quest startet, sobald er frei ist","quest_open_agent":"{agent} öffnen","quest_group_history":"Verlauf","drawer_quests_title":"Questtafel","drawer_quests_hint":"Gib einen Auftrag auf. Der passende Agent übernimmt ihn – passt niemand, schmiedet die Foundry einen.","quest_compose_placeholder":"Was soll erledigt werden? Zum Beispiel: die fünf wichtigsten Mails von heute","quest_compose_hint":"Strg+Enter schickt ab","quest_post":"Quest aufgeben","quest_posting":"Wird aufgegeben…","quest_group_active":"Auf der Tafel","quest_group_done":"Erledigt","quest_group_failed":"Gescheitert","quest_group_cancelled":"Abgebrochen","quest_empty":"Noch keine Quests. Gib die erste auf.","quest_state":{"open":"wartet auf jemanden","assigned":"zugeteilt","running":"in Arbeit","done":"erledigt","failed":"gescheitert","cancelled":"abgebrochen"},"quest_taken_by":"{agent} hat sie übernommen","quest_forged":"{agent} wurde dafür geschmiedet","quest_no_taker":"Noch niemand konnte sie übernehmen","quest_cancel":"Abbrechen","quest_retry":"Erneut versuchen","quest_result_label":"Übergabe","quest_open_label":"Noch offen","quest_refused":"Abgelehnt: {reason}","quest_age_now":"gerade eben","quest_age_min":"vor {n} Min.","quest_age_h":"vor {n} Std.","quest_age_d":"vor {n} Tagen","quest_close":"Schließen","quest_loading":"Tafel wird gelesen…","quest_open_ledger":"Agenten-Register öffnen","drawer_loading":"Plugin-Katalog wird gelesen…","drawer_empty":"Keine Plugins gefunden.","plugin_group_brain":"Gehirne","plugin_group_tool":"Werkzeuge","plugin_group_stt":"Sprache zu Text","plugin_group_tts":"Text zu Sprache","plugin_group_channel":"Kanäle","plugin_group_realtime":"Echtzeit-Stimme","plugin_group_wakeword":"Weckwörter","plugin_group_harness":"Harnesse","place_skills":"Skill-Schmiede","place_mcp":"Relais-Turm","place_cli":"Terminal-Cantina","drawer_skills_title":"Skill-Schmiede","drawer_skills_hint":"Alle Skills, die diese App kennt. Entwürfe, die ein Agent gelernt hat, warten hier auf deine Freigabe.","skills_group_draft":"Entwürfe, warten auf Freigabe","skills_group_custom":"Deine","skills_group_builtin":"Eingebaut","drawer_mcp_title":"Relais-Turm","drawer_mcp_hint":"Die MCP-Server, die diese App erreicht. Die Schüssel dreht sich, während ein Agent einen aufruft.","mcp_group_stdio":"Lokal (stdio)","mcp_group_http":"Entfernt (HTTP)","drawer_cli_title":"Terminal-Cantina","drawer_cli_hint":"Die Coding-CLIs und Sitze. Ein Agent sitzt hier am Terminal, solange eine Coding-Sitzung läuft.","cli_group_connected":"Verbunden","cli_group_installed":"Installiert, nicht verbunden","cli_group_missing":"Nicht installiert","place_comms":"Signalamt","place_desktop":"Steuerhaus","place_web":"Die Warte","place_models":"Kesselhaus","place_civic":"Rathaus","place_gallery":"Galerie","drawer_comms_title":"Signalamt","drawer_comms_hint":"Mail, Chat, Kontakte und Anrufe. Ein Agent steht hier, während er einer Person oder einem Kollegen schreibt.","comms_group_mail":"Mail und Chat","comms_group_people":"Menschen und Anrufe","drawer_desktop_title":"Steuerhaus","drawer_desktop_hint":"Die Hand an deinem Rechner: Klicks, Tasten, Fenster und was auf dem Bildschirm steht. Ein Agent steht hier, während er die Maschine bedient.","desktop_group_pointer":"Zeiger und Tasten","desktop_group_screen":"Bildschirm und Fenster","drawer_web_title":"Die Warte","drawer_web_hint":"Die Welt draußen: Websuche und der eigene Browser des Agenten. Ein Agent steht hier, während er etwas liest, das nicht dir gehört.","web_group_search":"Suchen und Abrufen","web_group_browser":"Der Browser des Agenten","drawer_models_title":"Kesselhaus","drawer_models_hint":"Wo ein lokales Modell denkt. Ein Agent steht hier, während sein eigenes Gehirn auf diesem Rechner rechnet.","drawer_models_body":"Ein Agent, dessen Anbieter keinen Schlüssel braucht, läuft auf diesem Rechner. Während sein Modell arbeitet, steht die Figur am Kesselhaus statt in einem Laden — die Arbeit ist das Denken, nicht ein Werkzeug.","drawer_civic_title":"Rathaus","drawer_civic_hint":"Räume und das Board. Ein Agent steht hier, während er mit den anderen in einem abgegrenzten Raum sitzt.","drawer_civic_body":"Ein Raum ist ein abgegrenztes Gespräch zwischen benannten Agenten: er öffnet, läuft und wird geschlossen. Alle in einem offenen Raum stehen so lange am Rathaus. Das Board listet, woran die Gesellschaft arbeitet.","drawer_gallery_title":"Galerie","drawer_gallery_hint":"Fertige Arbeit. Ein Agent trägt sein Ergebnis hier herein, sobald er eines abliefert.","drawer_gallery_body":"Jedes abgelieferte Ergebnis wird archiviert und im Bereich Visualisierung in voller Größe gezeigt — Seiten, Diagramme, Bilder. Die Figur trägt die Kiste ein paar Sekunden hinüber und geht dann zurück an die Arbeit.","card_comms_does":"Im Signalamt passiert alles, was jemandem schreibt: Mail, Chat, das Kontaktbuch und das Telefon, dazu der eine Nachrichtenweg zwischen Agenten. Die Isolatoren am Mast leuchten, während eine Nachricht läuft.","card_comms_how":"Verbinde ein Mail- oder Chat-Plugin oder füll das Kontaktbuch. Ein Agent mit diesen Händen geht hierher, sobald er einer Person oder einem Kollegen schreibt.","card_desktop_does":"Das Steuerhaus ist die Hand an deinem Rechner: eine App öffnen, klicken, tippen, scrollen, Fenster wechseln, lesen, was auf dem Bildschirm steht. Jedes dieser Werkzeuge stellt die Figur hinter diese Scheibe.","card_desktop_how":"Gib einem Agenten die Desktop-Werkzeuge. Achte auf die Hebel: er bedient deine echte Maschine, halte seine Berechtigungsgrenze also dort, wo du sie willst.","card_web_does":"Die Warte schaut auf das, was nicht dir gehört: Websuche und die eigene Browser-Sitzung des Agenten. Das Fernrohr zeigt aufs Meer, weil alles, was hier gelesen wird, von außerhalb der Insel kommt.","card_web_how":"Die Suche braucht ein Backend, der Browser wird einmal pro Agent installiert. Danach läuft beides ohne weiteres Zutun.","card_models_does":"Im Kesselhaus denkt ein Modell auf diesem Gerät. Ein Agent auf einem schlüssellosen, lokalen Anbieter steht hier, während sein eigenes Gehirn rechnet — statt im Laden eines Werkzeugs, das er gar nicht benutzt.","card_models_how":"Installiere im Bereich Lokale Modelle ein Modell und richte den Anbieter eines Agenten darauf. Nichts verlässt den Rechner.","card_civic_does":"Das Rathaus hält die Räume: ein abgegrenztes Gespräch zwischen benannten Agenten, das öffnet, läuft und geschlossen wird. Jedes Mitglied steht hier, solange der Raum offen ist.","card_civic_how":"Öffne einen Raum über das Board oder lass einen Orchestrator einen öffnen. Der Aushang davor zeigt, was in der Gesellschaft ansteht.","card_gallery_does":"In der Galerie landet fertige Arbeit. Sobald ein Agent ein Ergebnis abliefert, trägt er die Kiste hier herein — Seiten, Diagramme und Bilder werden dann in der App in voller Größe gezeigt.","card_gallery_how":"Nichts einzurichten: Jedes abgelieferte Ergebnis wird automatisch archiviert und öffnet sich im Bereich Visualisierung.","drawer_foundry_body":"Ein neuer Agent wird hier erschaffen und läuft aus dieser Tür zu seinem eigenen Haus im Ring. Erstelle einen über „Neu“ in der Agenten-Leiste; auch Avatar-Änderungen passieren hier drinnen.","place_market":"Marktplatz","place_hub":"Jarvis-Hub","place_workshop":"Werkstatt","place_archive":"Gedächtnis-Haus","drawer_memory_title":"Gedächtnis-Haus","drawer_memory_hint":"Das gemeinsame Gedächtnis der Agenten: geprüftes Team-Wissen, das Gedächtnis jedes Agenten und die Prüf-Warteschlange. Ein Agent geht hierher, wenn er sich erinnert oder etwas nachschlägt.","memory_search_placeholder":"Im Gedächtnis suchen…","memory_search_button":"Suchen","memory_hits":"Treffer","memory_no_hits":"Nichts gefunden.","memory_shared":"Team-Wissen","memory_empty_shared":"Noch kein geprüftes Team-Wissen. Vorschläge der Agenten landen unten in der Warteschlange.","memory_agents":"Gedächtnis je Agent","memory_notes":"{count} Notizen","memory_nothing_remembered":"Noch nichts gemerkt.","memory_queue":"Zu prüfen","memory_empty_queue":"Nichts zu prüfen.","memory_promote":"Ins Team-Wissen","memory_dismiss":"Geprüft","memory_open_wiki":"Wiki öffnen","place_harbor":"Hafentor","place_lighthouse":"Leuchtturm","place_gardens":"Gärten","place_solar":"Solarfeld","place_mine":"Die Mine"},"hooks":{"webhook":"Webhook","event_hook":"Integrations-Ereignis","connect":"Webhook verbinden","endpoint":"Webhook-URL","token":"Zugangsschlüssel","copy":"Schlüssel kopieren","copied":"Kopiert","rotate":"Schlüssel erneuern","rotate_confirm":"Schlüssel ersetzen? Bestehende Integrationen benötigen danach den neuen Schlüssel.","remote":"Externe Dienste benötigen eine erreichbare HTTPS-Adresse dieser Jarvis-Instanz.","auth":"JSON mit Authorization: Bearer <token> senden. Bei Wiederholungen denselben Idempotency-Key verwenden. Bei GitHub diesen Schlüssel als Webhook-Secret verwenden (HMAC-SHA256).","conditions":"Payload-Filter (JSON-Feldvergleich)","event_name":"Ereignisname, z. B. crm.customer.created","loading":"Verbindung wird geladen…","configured":"Verbindung bereit","source":"Die Ereignisquelle muss aktiv sein.","filter_hint":"Beispiel: {\\"data.status\\": \\"ready\\"}. Mit {} wird jede Payload angenommen."},"browser_live":{"live":"Live","manual":"Du steuerst den Browser","expand":"Browser vergrößern","collapse":"Browser verkleinern","back":"Zurück","forward":"Vorwärts","reload":"Neu laden","address":"Website-Adresse","tabs":"Browser-Tabs","new_tab":"Neuer Tab","screen":"Live-Browser von {0}","return_control":"An Agent zurückgeben","take_control":"Übernehmen / anmelden","cancel":"Auftrag stoppen","approval":"Browser-Aktion erlauben?","allow":"Erlauben","deny":"Ablehnen","repair":"Browser reparieren"}}'),n={society:e};export{n as default,e as society};
